-- Around My Dorm canonical seed 11-20
on conflict (id) do update set
  slug=excluded.slug, name=excluded.name, category=excluded.category, area=excluded.area,
  latitude=excluded.latitude, longitude=excluded.longitude, google_place_id=excluded.google_place_id,
  verified=excluded.verified, last_checked=excluded.last_checked, last_updated=excluded.last_updated, record=excluded.record;
